@startuml

class SensorController {
  + username : string
  + password : string
}

class Apartment {
  + address : string
}

class Inhabitant {
  + username : string
  + password : string
}

class Room {
  + description : string
}

abstract class Sensor {
  + vendorId : string
  + description : string
  + unit : Unit
}

class TemperatureSensor extends Sensor {
  + minValue : float
  + maxValue : float
}

class PowerSensor extends Sensor {
  + counterReading : float
}

enum Unit {
  CELSIUS
  WATT
}

class MeasuredValue {
  + timestamp : datetime
  + value : float
}

class EMonitor {}

class AlertMessage {}

Apartment "1" *-- "2..*" Room
Apartment "1" *-- "*" Inhabitant
SensorController "1" *-- "1" Apartment
SensorController "1" *-- "*" Inhabitant
SensorController "1" *-- "*" Sensor

Inhabitant "0..1" -- "*" Sensor : configures
Inhabitant "1" -- "0..1" Sensor : specifies threshold

Sensor "1" -- "1" Room
Sensor "1" -- "*" MeasuredValue
Sensor "1" -- "1" MeasuredValue : lastValue

EMonitor ..> Sensor : checks thresholds
EMonitor "1" -- "*" AlertMessage
AlertMessage "1" -- "1" Apartment

@enduml

